from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class NmsResponseV1(SchemaObject):
    downlink_from_nms = SchemaField(name='downlinkFromNMS', not_null=True)
    uplink_to_nms = SchemaField(name='uplinkToNMS', not_null=True)

    def __init__(self, downlink_from_nms, uplink_to_nms):
        self.downlink_from_nms = downlink_from_nms
        self.uplink_to_nms = uplink_to_nms

        super(NmsResponseV1, self).__init__()
